<?php $title='Settings';require __DIR__.'/_layout.php';if(!can_manage('settings'))exit('Forbidden');$keys=['site_name','site_description','contact_email','footer_text','default_seo_title','default_seo_description','social_facebook','social_instagram','social_x','social_youtube','social_telegram','posts_per_page','enable_comments','enable_registration'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($keys as $k){$v=trim($_POST[$k]??'');$st=db()->prepare("INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$st->execute([$k,$v]);}flash('success','Settings saved.');redirect('settings.php');}?><h1>Settings</h1><form class="form" method="post"><?=csrf_field()?><?php foreach($keys as $k):?><label><?=e(ucwords(str_replace('_',' ',$k)))?></label><input name="<?=e($k)?>" value="<?=e(setting($k,''))?>"><?php endforeach;?><button>Save settings</button></form><?php require __DIR__.'/_footer.php';?>